&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 1&quot;&gt;Das macht uns aus&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;💡 &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Innovationspotenzial:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; Bei Xebia liegt der Fokus auf Innovation und Pioniergeist. Du kannst deine kreativen Ideen entwickeln und innovative Gedanken teilen.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;🌱 &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Persönliches Wachstum:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; Wir glauben an persönliche Entwicklung für herausragende berufliche Erfahrungen. Entfalte dein Potenzial und wachse kontinuierlich.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;🤝 &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Gemeinschaft und Netzwerken:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; Xebia bildet eine Gemeinschaft von Technologie-Enthusiasten. Triff Fachleute aus verschiedenen Bereichen, teile Wissen und gestalte gemeinsam Innovationen.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;⚖️ &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Flexibilität:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; Wir schätzen die Work-Life-Balance. Passe deine Arbeitszeit an und finde eine Balance zwischen Karriere und persönlichem Leben.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;🎉 &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Tolle Social-Events:&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; Skitage, B2run, spontane Afterwork-Aperos, Weihnachts- und Sommerfeste – wir feiern gemeinsam.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;em&gt;&lt;span data-contrast=&quot;none&quot;&gt;Wenn du bereit bist, deine berufliche Reise zu erweitern, heissen wir dich bei Xebia herzlich willkommen.&lt;/span&gt;&lt;/em&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559738&amp;quot;:360,&amp;quot;335559739&amp;quot;:120,&amp;quot;335572071&amp;quot;:6,&amp;quot;335572072&amp;quot;:1,&amp;quot;335572073&amp;quot;:8657795,&amp;quot;469789798&amp;quot;:&amp;quot;single&amp;quot;}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Wir freuen uns auf dich!&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
